sql.where:
w.tenant_id = #{q.tenantId}

    AND w.log_type = #{q.logType}


    AND w.event_id = #{q.eventId}


    AND w.host_id = #{q.hostId}


    AND w.level = #{q.level}


    AND w.username LIKE CONCAT('%', #{q.username}, '%')


    AND (w.message LIKE CONCAT('%', #{q.keyword}, '%')
         OR w.username LIKE CONCAT('%', #{q.keyword}, '%'))


    AND w.event_time >= #{q.startTime}


    AND w.event_time <= #{q.endTime}

mapper.select:
SELECT COUNT(1)
FROM windows_event_logs
WHERE log_type = #{logType}
  AND tenant_id = #{tenantId}
  AND DATE(event_time) = CURDATE()
